WITH joined AS (SELECT s.*, b.status, b.discount FROM order_items s INNER JOIN orders b ON s.order_id = b.id) SELECT product_id, CASE WHEN unit_price >= 400 THEN 'HIGH' ELSE 'LOW' END AS unit_price_tier, ROUND(SUM(unit_price) / NULLIF(COUNT(CASE WHEN status = 'CANCELLED' THEN 1 END), 0), 2) AS unit_price_per_cancelled, COUNT(*) AS event_count, GROUPING(product_id) AS gid FROM joined GROUP BY ROLLUP (product_id, CASE WHEN unit_price >= 400 THEN 'HIGH' ELSE 'LOW' END) HAVING unit_price_per_cancelled > 0
